            if (plus <= 0) break;
            ans += plus;
        }
        for (int p : primes) {
            if ((ll)p * p * p <= n) {
                ans++;
            } else {
                break;
            }
        }
        printf("%lld\n", ans);
    }

    void run() {
        solve();
    }
};

int main() {
    F3V3 solver;
    solver.run();
    return 0;
